SELECT IF(c.np + c.na + c.ns + (c.ayh <> '') + (c.ibu <> '') = 0, '<mark>susunan ahli waris belum diisi - isi variabel 9701 s.d. 9704 dan 9718</mark>', CONCAT_WS(';', IF(c.np = 0, NULL, CONCAT(IF(LOCATE(';', c.pas) = 0, c.pas, CONCAT(REPLACE(SUBSTRING_INDEX(c.pas, ';', (LENGTH(c.pas) - LENGTH(REPLACE(c.pas, ';', '')) + 1) - 1), ';', ','), ' dan ', TRIM(SUBSTRING_INDEX(c.pas, ';', -1)))), IF(c.sx = 'P', ' (suami Pewaris)', IF(c.np > 1, ' (istri-istri Pewaris)', ' (istri Pewaris)')))), IF(c.na = 0, NULL, CONCAT(IF(LOCATE(';', c.ank) = 0, c.ank, CONCAT(REPLACE(SUBSTRING_INDEX(c.ank, ';', (LENGTH(c.ank) - LENGTH(REPLACE(c.ank, ';', '')) + 1) - 1), ';', ','), ' dan ', TRIM(SUBSTRING_INDEX(c.ank, ';', -1)))), IF(c.nap = 0, ' (anak laki-laki kandung Pewaris)', IF(c.nap = c.na, ' (anak perempuan kandung Pewaris)', ' (anak kandung Pewaris)')))), IF(c.ayh = '', NULL, CONCAT(c.ayh, ' (ayah kandung Pewaris)')), IF(c.ibu = '', NULL, CONCAT(c.ibu, ' (ibu kandung Pewaris)')), IF(c.ns = 0, NULL, CONCAT(IF(LOCATE(';', c.sdr) = 0, c.sdr, CONCAT(REPLACE(SUBSTRING_INDEX(c.sdr, ';', (LENGTH(c.sdr) - LENGTH(REPLACE(c.sdr, ';', '')) + 1) - 1), ';', ','), ' dan ', TRIM(SUBSTRING_INDEX(c.sdr, ';', -1)))), IF(c.nsp = 0, ' (saudara laki-laki Pewaris)', IF(c.nsp = c.ns, ' (saudara perempuan Pewaris)', ' (saudara Pewaris)')))))) AS data FROM (SELECT i.*, IF(i.pas = '', 0, LENGTH(i.pas) - LENGTH(REPLACE(i.pas, ';', '')) + 1) AS np, IF(i.ank = '', 0, LENGTH(i.ank) - LENGTH(REPLACE(i.ank, ';', '')) + 1) AS na, ROUND((LENGTH(LOWER(i.ank)) - LENGTH(REPLACE(LOWER(i.ank), ' binti ', ''))) / 7) AS nap, IF(i.sdr = '', 0, LENGTH(i.sdr) - LENGTH(REPLACE(i.sdr, ';', '')) + 1) AS ns, ROUND((LENGTH(LOWER(i.sdr)) - LENGTH(REPLACE(LOWER(i.sdr), ' binti ', ''))) / 7) AS nsp FROM (SELECT TRIM(TRAILING ';' FROM TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag.abt_data_teks WHERE no_var = 9701 AND perkara_id = '#perkara_id#' LIMIT 1) USING utf8), '\\', '/'), '"', '&quot;'), '''', '&#39;'), ''))) AS pas, TRIM(TRAILING ';' FROM TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag.abt_data_teks WHERE no_var = 9702 AND perkara_id = '#perkara_id#' LIMIT 1) USING utf8), '\\', '/'), '"', '&quot;'), '''', '&#39;'), ''))) AS ank, TRIM(TRAILING ';' FROM TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag.abt_data_teks WHERE no_var = 9703 AND perkara_id = '#perkara_id#' LIMIT 1) USING utf8), '\\', '/'), '"', '&quot;'), '''', '&#39;'), ''))) AS ayh, TRIM(TRAILING ';' FROM TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag.abt_data_teks WHERE no_var = 9704 AND perkara_id = '#perkara_id#' LIMIT 1) USING utf8), '\\', '/'), '"', '&quot;'), '''', '&#39;'), ''))) AS ibu, IF(IFNULL(CONVERT((SELECT data FROM aps_badilag.abt_data_teks WHERE no_var = 1025 AND perkara_id = '#perkara_id#' LIMIT 1) USING utf8), '') LIKE '%binti%', 'P', 'L') AS sx, TRIM(TRAILING ';' FROM TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag.abt_data_teks WHERE no_var = 9700 AND perkara_id = '#perkara_id#' LIMIT 1) USING utf8), '\\', '/'), '"', '&quot;'), '''', '&#39;'), ''))) AS dana, TRIM(TRAILING ';' FROM TRIM(IFNULL(REPLACE(REPLACE(REPLACE(CONVERT((SELECT data FROM aps_badilag.abt_data_teks WHERE no_var = 9718 AND perkara_id = '#perkara_id#' LIMIT 1) USING utf8), '\\', '/'), '"', '&quot;'), '''', '&#39;'), ''))) AS sdr) i) c